package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.isAvailableLocale
 */
public class LocaleUtils_isAvailableLocale_TriageGen1Test {

    @Test
    public void testIsAvailableLocale_WithAvailableLocale() {
        // Get an actual available locale from the utility itself to ensure truthiness
        Locale availableLocale = LocaleUtils.availableLocaleList().get(0);

        boolean result = LocaleUtils.isAvailableLocale(availableLocale);

        assertTrue("Expected locale to be available", result);
    }

    @Test
    public void testIsAvailableLocale_WithUnavailableLocale() {
        // Create a locale that is highly unlikely to be in the available set
        // Using a rare combination or a non-existent language/country
        Locale unavailableLocale = new Locale("zz", "ZZ");

        boolean result = LocaleUtils.isAvailableLocale(unavailableLocale);

        assertFalse("Expected locale to be unavailable", result);
    }

    @Test
    public void testIsAvailableLocale_WithNull() {
        // Testing null handling. 
        // Depending on implementation, contains(null) usually returns false in Sets.
        boolean result = LocaleUtils.isAvailableLocale(null);

        assertFalse("Expected result to be false when locale is null", result);
    }

    @Test
    public void testIsAvailableLocale_WithAllAvailableLocales() {
        // Iterate through all available locales to ensure coverage of the set contents
        for (Locale locale : LocaleUtils.availableLocaleList()) {
            assertTrue("Locale " + locale + " should be reported as available", 
                LocaleUtils.isAvailableLocale(locale));
        }
    }
}
